from typing import List
import sys
from functools import lru_cache

def solve_tsp(distances: List[List[int]]) -> int:
    n = len(distances)
    if n < 2:
        raise ValueError("The number of cities must be at least 2.")

    @lru_cache((n,) * n)
    def tsp(pos: int, visited: List[bool]) -> int:
        if not visited:
            return sys.maxsize
        if all(visited):
            return distances[pos][0]
        min_cost = sys.maxsize
        for i in range(n):
            if not visited[i] and i != pos:
                new_visited = visited.copy()
                new_visited[i] = True
                min_cost = min(min_cost, distances[pos][i] + tsp(i, new_visited))
        return min_cost

    visited = [False] * n
    return tsp(0, visited)
```

