from typing import List, Tuple
import sys

def read_distance_matrix(file_path: str) -> List[List[int]]:
    with open(file_path, 'r') as file:
        distances = [list(map(int, line.split())) for line in file]
        if len(distances) != len(distances[0]):
            raise ValueError("Invalid distance matrix.")
        return distances

def tour_cost(distances: List[List[int]], tour: List[int]) -> int:
    total_cost = 0
    for i in range(len(tour) - 1):
        total_cost += distances[tour[i]][tour[i + 1]]
    total_cost += distances[tour[-1]][tour[0]]
    return total_cost

def three_opt(distances: List[List[int]], tour: List[int]) -> List[int]:
    n = len(tour)
    for i in range(n - 2):
        for j in range(i + 2, n):
            if tour_cost(distances, tour[:i] + tour[j:] + tour[i:j]) < tour_cost(distances, tour):
                tour = tour[:i] + tour[j:] + tour[i:j]
                break
    return tour

def solve_tsp(distances: List[List[int]]) -> int:
    tour = list(range(len(distances)))
    tour = three_opt(distances, tour)
    return tour_cost(distances, tour)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python tsp.py <distance_matrix_file>")
        sys.exit(1)

    distances = read_distance_matrix(sys.argv[1])
    print(solve_tsp(distances))
