from typing import List, Tuple

def distance_matrix(cities: List[List[int]]) -> List[List[int]]:
    n = len(cities)
    matrix = [[0] * n for _ in range(n)]
    for i, city in enumerate(cities):
        for j, _ in enumerate(city):
            matrix[i][j] = city[i] if i != j else 0
    return matrix

def swap(matrix: List[List[int]], i: int, j: int) -> List[List[int]]:
    matrix[i], matrix[j] = matrix[j], matrix[i]
    return matrix

def tour_cost(matrix: List[List[int]], tour: List[int]) -> int:
    cost = 0
    for i in range(len(tour) - 1):
        cost += matrix[tour[i]][tour[i + 1]]
    cost += matrix[tour[-1]][tour[0]]
    return cost

def three_opt(matrix: List[List[int]], tour: List[int]) -> List[int]:
    n = len(tour)
    for i in range(1, n - 2):
        for j in range(i + 2, n):
            if tour_cost(matrix, swap(tour, i, j)) < tour_cost(matrix, tour):
                tour = swap(tour, i, j)
                for k in range(i + 1, j):
                    if tour_cost(matrix, swap(swap(tour, i, k), swap(tour, k, j))) < tour_cost(matrix, tour):
                        tour = swap(swap(tour, i, k), swap(tour, k, j))
    return tour

def solve_tsp(matrix: List[List[int]]) -> int:
    tour = list(range(len(matrix)))
    three_opt(distance_matrix(tour), tour)
    return tour_cost(matrix, tour)

