        count = 0
        for a, b, c in combinations:
            if is_right_triangle(a, b, c) and has_arithmetic_progression(*sorted([a, b, c])):
                count += 1
        return count

    def combinations_with_replacement(elements: List[int], r: int) -> List[Tuple[int, ...]]:
        n = len(elements)
        if r > n:
            return []
        if r == 1:
            return [(elements[i],) for i in range(n)]
        if r == n:
            return [tuple(elements)]

        combinations = []
        for i in range(n):
            for c in combinations_with_replacement(elements, r - 1):
                combinations.append((elements[i],) + c)
        return combinations

