    materials, hours = 0, 0
    for _, _, rm, h in zip(range(1, 3), range(1, 3), raw_material_requirement(range(1, 3)), [30, 15]):
        materials += rm * m
        hours += h * m + h * n
        if materials > raw_materials or hours > working_hours:
