        while vacant_units > 0:
            if vacant_units >= vacancies_per_increment:
                vacant_units -= vacancies_per_increment
            else:
                vacant_units = 0
            revenue += (num_units - vacant_units) * (rent - base_rent)
            rent += rent_increment
        return revenue

