import math

def count_grid_ways(numbers: List[int]) -> int:
    total = sum(numbers)
    if total % 3 != 0:
        return 0

    target_sums = [total - 3 * i for i in range(math.floor(total / 3), -1, -1)]
    ways = 0
    for target_sum in target_sums:
        ways += binomial_coefficient(len(numbers), 6) * sum([binomial_coefficient(numbers.count(i), 3) for i in range(2, 12) if i <= target_sum])
    return ways

def binomial_coefficient(n: int, k: int) -> int:
    if k > n or k < 0:
        return 0
    num = 1
    den = 1
    for i in range(k, n - k + 1):
        num *= i
        den *= i + k
    return num // den

