from typing import Tuple
import math
import numpy as np

def cubic_function(a: float, b: float, c: float, d: float) -> callable:
    """Cubic function y = f(x)"""
    def f(x: float) -> float:
        if x < -1:
            return np.nan
        return a * x**3 + b * x**2 + c * x + d
    return f

def road(x: float) -> float:
    """Road function g(x)"""
    if x <= 2:
        return np.nan
    return (x + 1) / (x - 2)

def distance_point_to_line(p: Tuple[float, float], l: callable, x0: float) -> float:
    """Distance from point (p[0], p[1]) to line l(x) at x0"""
    y0 = l(x0)
    return math.sqrt((p[0] - x0)**2 + (p[1] - y0)**2)

def find_min_distance(cubic: callable, road_x0: float) -> float:
    """Minimum distance between a point on the cubic curve and the road"""
    def gradient(x: float) -> float:
        dy = cubic(x) - cubic(road_x0)
        dx = x - road_x0
        return dy / dx if dx != 0 else np.nan

    def cubic_derivative(x: float) -> float:
        return 3 * cubic(x)**2 - 2 * cubic(x + 1) - 2 * cubic(x - 1)

    def newton_raphson(x0: float, f: callable, df: callable) -> float:
        epsilon = 1e-6
        while True:
            x1 = x0 - f(x0) / df(x0)
            if abs(x1 - x0) < epsilon:
                return x1
            x0 = x1

    x = newton_raphson(road_x0, gradient, cubic_derivative)
    return round(distance_point_to_line((x, cubic(x)), road, road_x0) * 10, 2)

